let busyRequests=0,busyShownAt=0,busyShowTimer=null,busyHideTimer=null;
function showGlobalBusy(){const bar=document.getElementById('globalBusy'),label=document.getElementById('globalBusyLabel');if(!bar)return;clearTimeout(busyHideTimer);if(!bar.classList.contains('active')){busyShownAt=Date.now();bar.classList.add('active');bar.setAttribute('aria-hidden','false')}if(label){label.classList.add('active');label.setAttribute('aria-hidden','false')}}
function beginBusy(){busyRequests++;if(busyRequests===1){clearTimeout(busyHideTimer);busyShowTimer=setTimeout(showGlobalBusy,180)}}
function endBusy(){busyRequests=Math.max(0,busyRequests-1);if(!busyRequests){clearTimeout(busyShowTimer);const bar=document.getElementById('globalBusy'),label=document.getElementById('globalBusyLabel');if(!bar)return;const wait=Math.max(0,360-(Date.now()-busyShownAt));busyHideTimer=setTimeout(()=>{if(!busyRequests){bar.classList.remove('active');bar.setAttribute('aria-hidden','true');if(label){label.classList.remove('active');label.setAttribute('aria-hidden','true')}}},wait)}}
const nativeFetch=window.fetch.bind(window);
window.fetch=async(...args)=>{beginBusy();try{return await nativeFetch(...args)}finally{endBusy()}};
