$('login').addEventListener('submit',async e=>{e.preventDefault();clearNotice();let name=$('lu').value.trim().toLowerCase(),password=$('lp').value;if(!/^[a-z0-9_]{3,24}$/.test(name))return notice('Enter a valid username.');$('lb').disabled=true;try{let{data,error}=await db.auth.signInWithPassword({email:usernameEmail(name),password});if(error)throw error;let{data:p,error:pe}=await db.from('jvault_profiles').select('username').eq('user_id',data.user.id).maybeSingle();if(pe||!p){await db.auth.signOut();throw Error('This account is not registered as the JVault owner.')}user=data.user;profile=p;await showApp()}catch(x){notice(x.message==='Invalid login credentials'?'Incorrect username or password.':x.message)}finally{$('lb').disabled=false}});
async function showApp(){ $('auth').classList.add('hidden');$('app').classList.remove('hidden');$('uname').innerHTML=esc(profile.username)+'<br><small>Vault owner</small>';$('avatar').textContent=profile.username[0].toUpperCase();$('today').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date()).toUpperCase();await Promise.all([loadFiles(),loadFolders(),loadPages(),loadReminders(),loadActivity()]);wire();checkDueReminders();if(!window.jvaultReminderTimer)window.jvaultReminderTimer=setInterval(checkDueReminders,60000);registerSW()}
async function loadFiles(){if(!user||loading)return;loading=true;try{let{data,error}=await db.from('jvault_files').select('*').eq('owner_id',user.id).order('created_at',{ascending:false});if(error)throw error;files=data||[];renderFiles()}catch(e){toast('Files failed to load: '+e.message,true)}finally{loading=false}}
async function loadFolders(){let{data,error}=await db.from('jvault_folders').select('*').eq('owner_id',user.id).order('name');if(error){toast('Folders failed to load: '+error.message,true);return}folders=data||[];$('scat').textContent=folders.length}
async function loadPages(){let{data,error}=await db.from('jvault_pages').select('*').eq('owner_id',user.id).order('updated_at',{ascending:false});if(error){toast('Notes failed to load: '+error.message,true);return}pages=data||[];$('noteCount').textContent=pages.filter(n=>!n.deleted_at&&!n.is_archived).length;if(activeNote&&!pages.some(n=>n.id===activeNote&&!n.deleted_at))activeNote=null;renderNotesList()}
async function loadReminders(){let{data,error}=await db.from('jvault_reminders').select('*').eq('owner_id',user.id).order('due_at');if(error){toast('Reminders failed to load: '+error.message,true);return}reminders=data||[];$('reminderCount').textContent=reminders.filter(r=>!r.is_done).length;renderReminders()}
async function loadActivity(){let{data,error}=await db.from('jvault_activity').select('*').eq('owner_id',user.id).order('created_at',{ascending:false}).limit(80);if(error)return;activity=data||[];renderActivity()}
async function log(action,type,id,details={}){try{await db.from('jvault_activity').insert({owner_id:user.id,action,target_type:type,target_id:id||null,details});if(page==='activity')await loadActivity()}catch(e){}}
function isImage(f){return /^image\//i.test(f.mime_type||'')||/\.(apng|avif|bmp|gif|jpe?g|png|svg|tiff?|webp|heic|heif)$/i.test(f.name||'')}
function isPdf(f){return f.mime_type==='application/pdf'||/\.pdf$/i.test(f.name)}
function visibleFiles(){let q=$('search').value.trim().toLowerCase(),items=files.filter(f=>!f.deleted_at);if(view==='trash')items=files.filter(f=>!!f.deleted_at);if(view==='favorites')items=items.filter(f=>f.is_favorite);if(view==='recent')items=items.slice(0,30);if(currentFolder)items=items.filter(f=>f.folder_id===currentFolder);if(view==='folders'&&!currentFolder)items=items.filter(f=>!f.folder_id);if(view==='tags'){items=items.filter(f=>(f.tags||[]).length)}if($('filter').value)items=items.filter(f=>(f.category||'Uncategorized')===$('filter').value);if(q)items=items.filter(f=>(f.name+' '+(f.category||'')+' '+(f.note||'')+' '+(f.tags||[]).join(' ')).toLowerCase().includes(q));let sort=$('sort').value;if(sort==='old')items.sort((a,b)=>new Date(a.created_at)-new Date(b.created_at));if(sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='size')items.sort((a,b)=>b.size_bytes-a.size_bytes);return items}
function renderFiles(){let live=files.filter(f=>!f.deleted_at),used=live.reduce((s,f)=>s+Number(f.size_bytes||0),0);$('sf').textContent=live.length;$('ss').textContent=bytes(used);$('statDocs').textContent=live.length;$('statFavorites').textContent=live.filter(f=>f.is_favorite).length;$('usageText').textContent=bytes(used)+' used';let cats=[...new Set(live.map(f=>f.category||'Uncategorized'))].sort();let old=$('filter').value;$('filter').innerHTML='<option value="">All categories</option>'+cats.map(c=>'<option>'+esc(c)+'</option>').join('');$('filter').value=cats.includes(old)?old:'';let items=visibleFiles(),q=$('search').value.trim().toLowerCase(),noteHits=q?pages.filter(n=>!n.deleted_at&&(n.title+' '+n.content+' '+(n.tags||[]).join(' ')).toLowerCase().includes(q)).slice(0,8):[],noteHtml=noteHits.map(n=>'<button class="note-search-hit" data-note-result="'+n.id+'"><strong>Note · '+esc(n.title)+'</strong><small>'+esc((n.content||'').slice(0,110))+'</small></button>').join('');$('pageTitle').innerHTML=({all:'All files',recent:'Recent files',favorites:'Favorites',folders:'Folders',tags:'Tagged files',trash:'Recycle bin'}[view]||'Your files')+'<span>.</span>';$('filesTitle').textContent=({all:'Your files',recent:'Recently added',favorites:'Favorites',folders:currentFolder?'Folder contents':'Your folders',tags:'Tagged files',trash:'Recently deleted'}[view]||'Your files');$('pageSubtitle').textContent=view==='trash'?'Deleted items stay here until you permanently remove them.':'A clear view of everything you keep.';$('newFolder').classList.toggle('hidden',view==='trash');$('deleteAll').classList.toggle('hidden',view==='trash');$('folderCrumb').classList.toggle('hidden',!currentFolder);if(currentFolder){let f=folders.find(x=>x.id===currentFolder);$('folderCrumb').innerHTML='<button data-action="folder-root">Folders</button> / '+esc(f?.name||'Folder')+' <button data-action="folder-up">Clear</button>'}let folderCards=view==='folders'&&!currentFolder?folders.map(f=>'<div class="file-entry folder-entry"><div class="file-main"><div class="file-ext">DIR</div><div><strong>'+esc(f.name)+'</strong><small>'+files.filter(x=>x.folder_id===f.id&&!x.deleted_at).length+' items</small></div></div><div class="file-actions"><button class="icon-action" data-action="open-folder" data-id="'+f.id+'" title="Open folder">↗</button><button class="icon-action" data-action="rename-folder" data-id="'+f.id+'" title="Rename folder">✎</button><button class="icon-action" data-action="delete-folder" data-id="'+f.id+'" title="Delete folder">×</button></div></div>').join(''):'';if(!items.length&&!folderCards&&!noteHtml){$('list').innerHTML='<div class="empty"><strong>'+(view==='trash'?'Your bin is empty':'Nothing here yet')+'</strong><p>'+(view==='trash'?'Deleted files will appear here.':'Upload a file or create a folder to get started.')+'</p></div>'}else{$('list').classList.toggle('file-grid',$('layoutMode').value==='grid');$('list').innerHTML=noteHtml+folderCards+items.map(fileRow).join('')}updateBulk()}
function fileRow(f){let ext=(f.name.split('.').pop()||'FILE').slice(0,4).toUpperCase(),date=new Date(f.created_at).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});let tags=(f.tags||[]).map(t=>'<span class="tag-chip">'+esc(t)+'</span>').join('');let actions=f.deleted_at?'<button class="icon-action" data-action="restore" data-id="'+f.id+'" title="Restore">↶</button><button class="icon-action" data-action="purge" data-id="'+f.id+'" title="Delete permanently">×</button>':'<button class="icon-action '+(f.is_favorite?'fav':'')+'" data-action="favorite" data-id="'+f.id+'" title="Favorite">☆</button><button class="icon-action" data-action="preview" data-id="'+f.id+'" title="Preview">⌕</button><button class="icon-action" data-action="file-note" data-id="'+f.id+'" title="File note">▧</button><button class="icon-action" data-action="download" data-id="'+f.id+'" title="Download">↓</button><button class="icon-action" data-action="rename" data-id="'+f.id+'" title="Rename">✎</button><button class="icon-action" data-action="tags" data-id="'+f.id+'" title="Edit tags">⌑</button><button class="icon-action" data-action="category" data-id="'+f.id+'" title="Change category">≡</button><button class="icon-action" data-action="move" data-id="'+f.id+'" title="Move to folder">⇢</button><button class="icon-action" data-action="versions" data-id="'+f.id+'" title="Version history">◷</button><button class="icon-action" data-action="share" data-id="'+f.id+'" title="Create secure share link">↗</button><button class="icon-action" data-action="trash" data-id="'+f.id+'" title="Move to bin">×</button>';return '<article class="file-entry"><div class="file-main"><input type="checkbox" data-select="'+f.id+'" '+(selected.has(f.id)?'checked':'')+' aria-label="Select '+esc(f.name)+'"><div class="file-ext">'+esc(ext)+'</div><div style="min-width:0"><strong title="'+esc(f.name)+'">'+esc(f.name)+'</strong><small>'+bytes(f.size_bytes)+' · '+date+(f.checksum_sha256?' · verified':'')+'</small></div></div><div class="file-cat">'+esc(f.category||'Uncategorized')+'</div><div class="file-date">'+date+'</div><div class="file-actions">'+actions+'</div>'+(tags?'<div class="file-tags">'+tags+'</div>':'')+'</article>'}
function updateBulk(){let n=visibleFiles().length;$('bulkBar').classList.toggle('hidden',n===0||view==='trash');$('selectedCount').textContent=selected.size+' selected';$('selectVisible').checked=n>0&&visibleFiles().every(f=>selected.has(f.id));$('downloadSelected').disabled=!selected.size;$('deleteSelected').disabled=!selected.size}
async function activityLog(action,type,id,details){await log(action,type,id,details);loadActivity()}
async function uploadFiles(list){let valid=[...list].filter(f=>f.size<=MAX_FILE);if(valid.length!==list.length)toast('Files over 50 MB were skipped.',true);if(!valid.length)return;let ok=0,done=0;$('uploadProgress').classList.remove('hidden');$('upload').disabled=true;for(let file of valid){try{let hash=await sha256(file),duplicate=files.find(f=>!f.deleted_at&&f.checksum_sha256===hash);if(duplicate&&!confirm('This file already exists as “'+duplicate.name+'”. Upload another copy?')){done++;continue}let clean=file.name.normalize('NFKC').replace(/[^a-zA-Z0-9._ -]/g,'_').replace(/\s+/g,'_').slice(0,180)||'document',path=user.id+'/'+crypto.randomUUID()+'-'+clean;let{error:up}=await db.storage.from(BUCKET).upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type||'application/octet-stream'});if(up)throw up;let{data,error}=await db.from('jvault_files').insert({owner_id:user.id,name:file.name,storage_path:path,size_bytes:file.size,mime_type:file.type||'application/octet-stream',category:'Uncategorized',folder_id:currentFolder,checksum_sha256:hash}).select().single();if(error){await db.storage.from(BUCKET).remove([path]);throw error}ok++;await log('Uploaded file','file',data.id,{name:file.name})}catch(e){toast('Upload failed: '+e.message,true)}done++;$('uploadStatus').textContent='Uploading files';$('uploadPercent').textContent=Math.round(done/valid.length*100)+'%';$('uploadProgressFill').style.width=done/valid.length*100+'%';$('uploadDetail').textContent=done+' of '+valid.length+' processed'}$('uploadProgress').classList.add('hidden');$('upload').disabled=false;$('picker').value='';await loadFiles();toast(ok+' file(s) uploaded.')}
async function sha256(file){let buf=await file.arrayBuffer(),hash=await crypto.subtle.digest('SHA-256',buf);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')}
async function signed(file,download=false){let{data,error}=await db.storage.from(BUCKET).createSignedUrl(file.storage_path,120,{download:download?file.name:false});if(error)throw error;return data.signedUrl}
async function editFileNote(f){modal('Note · '+f.name,'<textarea id="fileNoteText" rows="10" style="width:100%;min-height:220px;padding:12px;border:1px solid #fff;border-radius:12px;background:#ffffffb5;color:#45657e;resize:vertical">'+esc(f.note||'')+'</textarea>','<button class="secondary-btn" data-modal-close>Cancel</button><button id="saveFileNote" class="primary-btn">Save note</button>');$('saveFileNote').onclick=async()=>{let{error}=await db.from('jvault_files').update({note:$('fileNoteText').value,updated_at:new Date().toISOString()}).eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);f.note=$('fileNoteText').value;$('modalRoot').innerHTML='';await log('Updated file note','file',f.id,{name:f.name});toast('File note saved')}}
async function preview(f){let url=await signed(f);let body=isImage(f)?'<img class="preview-image" src="'+url+'" alt="'+esc(f.name)+'">':isPdf(f)?'<iframe class="preview-frame" src="'+url+'"></iframe>':'<div class="empty"><strong>Preview unavailable for this format</strong><p>Download the file to open it on your device.</p><a href="'+url+'" target="_blank" rel="noopener">Open file</a></div>';modal('Preview · '+f.name,body,'<button class="secondary-btn" data-modal-close>Close</button><a class="primary-btn" href="'+url+'" target="_blank" rel="noopener">Open / download</a>');await db.from('jvault_files').update({last_accessed_at:new Date().toISOString()}).eq('id',f.id)}
function modal(title,body,actions=''){let root=$('modalRoot');root.innerHTML='<div class="modal-backdrop" data-modal-backdrop><section class="modal-card"><header class="modal-head"><h3>'+esc(title)+'</h3><button class="modal-close" data-modal-close>×</button></header><div class="modal-body">'+body+'</div><footer class="modal-actions">'+actions+'</footer></section></div>';root.querySelector('[data-modal-backdrop]').addEventListener('click',e=>{if(e.target.dataset.modalBackdrop!==undefined||e.target.closest('[data-modal-close]'))root.innerHTML=''})}
async function softDelete(f){if(!confirm('Move “'+f.name+'” to the recycle bin?'))return;let{error}=await db.from('jvault_files').update({deleted_at:new Date().toISOString()}).eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);selected.delete(f.id);await log('Moved file to recycle bin','file',f.id,{name:f.name});await loadFiles()}
async function restoreFile(f){let{error}=await db.from('jvault_files').update({deleted_at:null}).eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);await log('Restored file','file',f.id,{name:f.name});await loadFiles()}
async function purgeFile(f){if(!confirm('Permanently delete “'+f.name+'” and its saved versions? This cannot be undone.'))return;let{data:vs}=await db.from('jvault_file_versions').select('storage_path').eq('file_id',f.id).eq('owner_id',user.id);let paths=[f.storage_path,...(vs||[]).map(v=>v.storage_path)];let{error:se}=await db.storage.from(BUCKET).remove(paths);if(se)return toast(se.message,true);let{error}=await db.from('jvault_files').delete().eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);await log('Permanently deleted file','file',f.id,{name:f.name});await loadFiles()}
async function renameFile(f){let name=prompt('Rename file',f.name);if(name===null)return;name=name.trim();if(!name||name.length>255)return toast('Name must be 1–255 characters.',true);let{error}=await db.from('jvault_files').update({name,updated_at:new Date().toISOString()}).eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);await log('Renamed file','file',f.id,{name});await loadFiles()}
async function changeCategory(f){let category=prompt('Category name (max 40 characters)',f.category||'Uncategorized');if(category===null)return;category=category.trim().slice(0,40)||'Uncategorized';let{error}=await db.from('jvault_files').update({category,updated_at:new Date().toISOString()}).eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);f.category=category;await log('Changed file category','file',f.id,{category});await loadFiles()}
async function moveFile(f){modal('Move file','<select id="moveFolder"><option value="">Root library</option>'+folders.map(x=>'<option value="'+x.id+'" '+(f.folder_id===x.id?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select>','<button class="secondary-btn" data-modal-close>Cancel</button><button id="confirmMove" class="primary-btn">Move file</button>');$('confirmMove').onclick=async()=>{let{error}=await db.from('jvault_files').update({folder_id:$('moveFolder').value||null,updated_at:new Date().toISOString()}).eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);$('modalRoot').innerHTML='';await log('Moved file','file',f.id,{folderId:$('moveFolder').value||null});await loadFiles()}}
async function editTags(f){let value=prompt('Tags, separated by commas', (f.tags||[]).join(', '));if(value===null)return;let tags=[...new Set(value.split(',').map(t=>t.trim().toLowerCase()).filter(Boolean))].slice(0,20);let{error}=await db.from('jvault_files').update({tags,updated_at:new Date().toISOString()}).eq('id',f.id).eq('owner_id',user.id);if(error)return toast(error.message,true);await log('Updated file tags','file',f.id,{tags});await loadFiles()}
async function createFolder(){let name=prompt('Folder name');if(!name)return;let{error}=await db.from('jvault_folders').insert({owner_id:user.id,name:name.trim(),parent_id:currentFolder});if(error)return toast(error.message,true);await log('Created folder','folder',null,{name});await loadFolders();view='folders';currentFolder=null;switchPage('files');renderFiles()}
async function folderAction(action,id){let f=folders.find(x=>x.id===id);if(!f)return;if(action==='open-folder'){currentFolder=id;view='folders';renderFiles()}if(action==='rename-folder'){let name=prompt('Rename folder',f.name);if(name===null)return;let{error}=await db.from('jvault_folders').update({name:name.trim(),updated_at:new Date().toISOString()}).eq('id',id);if(error)return toast(error.message,true);await loadFolders();renderFiles()}if(action==='delete-folder'){if(!confirm('Delete folder “'+f.name+'”? Files inside will be moved to the root.'))return;let{error}=await db.from('jvault_folders').delete().eq('id',id).eq('owner_id',user.id);if(error)return toast(error.message,true);currentFolder=null;await loadFolders();await loadFiles()}}
async function saveVersion(f,file){let{data:versions,error:ve}=await db.from('jvault_file_versions').select('*').eq('file_id',f.id).eq('owner_id',user.id).order('version_number',{ascending:false});if(ve)throw ve;let version=(versions?.[0]?.version_number||0)+1,path=user.id+'/'+crypto.randomUUID()+'-'+file.name;let{error:up}=await db.storage.from(BUCKET).upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});if(up)throw up;let{error:ins}=await db.from('jvault_file_versions').insert({owner_id:user.id,file_id:f.id,storage_path:f.storage_path,version_number:version,size_bytes:f.size_bytes});if(ins){await db.storage.from(BUCKET).remove([path]);throw ins}let{error:upd}=await db.from('jvault_files').update({storage_path:path,size_bytes:file.size,mime_type:file.type||'application/octet-stream',checksum_sha256:await sha256(file),updated_at:new Date().toISOString()}).eq('id',f.id).eq('owner_id',user.id);if(upd)throw upd;await log('Uploaded new version','file',f.id,{version});await loadFiles()}
async function versions(f){let{data,error}=await db.from('jvault_file_versions').select('*').eq('file_id',f.id).eq('owner_id',user.id).order('version_number',{ascending:false});if(error)return toast(error.message,true);let html='<p>Current version · '+bytes(f.size_bytes)+'</p>'+(data||[]).map(v=>'<div class="activity-row"><div><strong>Version '+v.version_number+'</strong><small>'+new Date(v.created_at).toLocaleString()+' · '+bytes(v.size_bytes)+'</small></div><button class="secondary-btn" data-version-download="'+v.id+'">Download</button><button class="secondary-btn" data-version-restore="'+v.id+'">Restore</button></div>').join('')+'<label>Upload a replacement version</label><input id="versionPicker" type="file">';modal('Version history',html,'<button class="secondary-btn" data-modal-close>Close</button><button class="primary-btn" id="saveVersionBtn">Save new version</button>');$('saveVersionBtn').onclick=async()=>{let file=$('versionPicker').files[0];if(!file)return toast('Choose a file first.',true);try{await saveVersion(f,file);$('modalRoot').innerHTML='';toast('New version saved.')}catch(e){toast('Version failed: '+e.message,true)}};$('modalRoot').querySelectorAll('[data-version-download],[data-version-restore]').forEach(b=>b.onclick=async()=>{let v=data.find(x=>x.id===b.dataset.versionDownload||x.id===b.dataset.versionRestore);if(b.dataset.versionRestore){if(!confirm('Restore version '+v.version_number+' as the current file?'))return;try{let{data:s,error:se}=await db.storage.from(BUCKET).createSignedUrl(v.storage_path,120);if(se)throw se;let response=await fetch(s.signedUrl),blob=await response.blob(),path=user.id+'/'+crypto.randomUUID()+'-restored-'+f.name;let{error:up}=await db.storage.from(BUCKET).upload(path,blob,{upsert:false,contentType:f.mime_type||'application/octet-stream'});if(up)throw up;let{data:vs}=await db.from('jvault_file_versions').select('version_number').eq('file_id',f.id).order('version_number',{ascending:false}).limit(1);let{error:ins}=await db.from('jvault_file_versions').insert({owner_id:user.id,file_id:f.id,storage_path:f.storage_path,version_number:(vs?.[0]?.version_number||0)+1,size_bytes:f.size_bytes});if(ins)throw ins;let{error:upd}=await db.from('jvault_files').update({storage_path:path,size_bytes:blob.size,updated_at:new Date().toISOString()}).eq('id',f.id);if(upd)throw upd;await log('Restored file version','file',f.id,{version:v.version_number});$('modalRoot').innerHTML='';await loadFiles();toast('Version restored')}catch(e){toast('Restore failed: '+e.message,true)}return}let{data:d,error:e}=await db.storage.from(BUCKET).createSignedUrl(v.storage_path,120);if(e)return toast(e.message,true);window.open(d.signedUrl,'_blank','noopener')})}
async function shareFile(f){let{data:{session}}=await db.auth.getSession();if(!session)return;let response=await fetch(FUNCTION_URL+'/share-create',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token},body:JSON.stringify({fileId:f.id,expiresIn:86400})});let result=await response.json().catch(()=>({}));if(!response.ok)return toast(result.error||'Could not create share link.',true);modal('Secure share link','<p>This private link expires in 24 hours. Anyone with it can download this file until it expires or you revoke it.</p><input id="shareUrl" readonly value="'+esc(result.url)+'">','<button class="secondary-btn" data-modal-close>Close</button><button id="revokeShares" class="quiet-danger">Revoke all links</button><button id="copyShare" class="primary-btn">Copy link</button>');$('copyShare').onclick=async()=>{await navigator.clipboard.writeText(result.url);toast('Share link copied.')};$('revokeShares').onclick=async()=>{let r=await fetch(FUNCTION_URL+'/share-revoke',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+session.access_token},body:JSON.stringify({fileId:f.id})}),j=await r.json().catch(()=>({}));if(!r.ok)return toast(j.error||'Could not revoke links.',true);$('modalRoot').innerHTML='';toast('All active links revoked.')}}
function switchPage(target){page=target;if(innerWidth<=760)$('app').classList.remove('sidebar-open');document.querySelectorAll('.page-view').forEach(x=>x.classList.remove('active'));let id=target==='files'?'filesPage':target+'Page';$(id)?.classList.add('active');document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===target||(target==='files'&&b.dataset.view===view)));$('crumbCurrent').textContent=target==='files'?({all:'All files',recent:'Recent',favorites:'Favorites',folders:'Folders',tags:'Tags',trash:'Recycle bin'}[view]||'Files'):target[0].toUpperCase()+target.slice(1);if(target==='files')renderFiles();if(target==='notes')renderNotesList();if(target==='reminders')renderReminders();if(target==='activity')renderActivity()}
function renderNotesList(){let active=pages.find(n=>n.id===activeNote);let list=pages;$('notesList').innerHTML=list.length?list.map(n=>'<button class="note-list-item '+(n.id===activeNote?'active':'')+'" data-note-id="'+n.id+'"><strong>'+(n.is_pinned?'◆ ':'')+esc(n.title)+'</strong><small>'+new Date(n.updated_at).toLocaleDateString()+' · '+(n.content||'').length+' chars</small></button>').join(''):'<div class="empty"><strong>No notes yet</strong><p>Create a note to start.</p></div>';if(active){$('noteTitle').value=active.title;$('noteContent').value=active.content;$('noteChars').textContent=active.content.length+' characters';$('noteSaveStatus').textContent='Saved';$('pinNote').textContent=active.is_pinned?'Unpin':'Pin';$('archiveNote').textContent=active.is_archived?'Unarchive':'Archive';$('deleteNote').textContent=active.deleted_at?'Restore note':'Move to bin';$('noteEditor')?.classList.remove('hidden')}else if(!activeNote){$('noteTitle').value='';$('noteContent').value='';$('noteChars').textContent='0 characters';$('noteSaveStatus').textContent='Choose a note or create one.'}}
async function createNote(title='Untitled note',content=''){clearTimeout(noteTimer);await saveNote();let{data,error}=await db.from('jvault_pages').insert({owner_id:user.id,title,content}).select().single();if(error)return toast(error.message,true);pages.unshift(data);activeNote=data.id;renderNotesList();$('noteTitle').focus();await log('Created note','note',data.id,{title})}
async function saveNote(){let n=pages.find(x=>x.id===activeNote);if(!n)return;let title=$('noteTitle').value.trim()||'Untitled note',content=$('noteContent').value;$('noteSaveStatus').textContent='Saving…';let{data,error}=await db.from('jvault_pages').update({title,content,updated_at:new Date().toISOString()}).eq('id',n.id).eq('owner_id',user.id).select().single();if(error){$('noteSaveStatus').textContent='Save failed';toast(error.message,true);return}Object.assign(n,data);$('noteSaveStatus').textContent='All changes saved';$('noteChars').textContent=content.length.toLocaleString()+' characters';renderNotesList()}
async function noteAction(action){let n=pages.find(x=>x.id===activeNote);if(!n)return;if(action==='pin'||action==='archive'){let key=action==='pin'?'is_pinned':'is_archived';let{error}=await db.from('jvault_pages').update({[key]:!n[key],updated_at:new Date().toISOString()}).eq('id',n.id);if(error)return toast(error.message,true);n[key]=!n[key];renderNotesList()}if(action==='delete'){if(n.deleted_at){let{error}=await db.from('jvault_pages').update({deleted_at:null}).eq('id',n.id);if(error)return toast(error.message,true);toast('Note restored')}else{if(!confirm('Move this note to the recycle bin?'))return;let{error}=await db.from('jvault_pages').update({deleted_at:new Date().toISOString()}).eq('id',n.id);if(error)return toast(error.message,true);toast('Note moved to bin')}activeNote=null;await loadPages();renderNotesList()}}
function reminderCountdown(dueAt){let ms=new Date(dueAt).getTime()-Date.now();if(ms<=0)return ms< -60000?'Overdue':'Due now';let mins=Math.floor(ms/60000),days=Math.floor(mins/1440),hours=Math.floor((mins%1440)/60),minutes=mins%60;return days?days+'d '+hours+'h remaining':hours?hours+'h '+minutes+'m remaining':minutes+'m remaining'}
function renderReminders(){$('reminderList').innerHTML=reminders.length?reminders.map(r=>'<div class="reminder-item '+(r.is_done?'done':'')+'"><input type="checkbox" data-reminder-done="'+r.id+'" '+(r.is_done?'checked':'')+'><div class="reminder-copy"><strong>'+esc(r.title)+'</strong><small>'+new Date(r.due_at).toLocaleString()+'</small><small class="reminder-countdown">'+(r.is_done?'Completed':reminderCountdown(r.due_at))+'</small></div><button class="text-btn" data-reminder-delete="'+r.id+'">Delete</button></div>').join(''):'<div class="empty"><strong>No reminders</strong><p>Add a reminder to keep a task visible.</p></div>'}
async function renderActivity(){ $('activityList').innerHTML=activity.length?activity.map(a=>'<div class="activity-row"><span class="activity-dot"></span><div><strong>'+esc(a.action)+'</strong><small>'+new Date(a.created_at).toLocaleString()+(a.details?.name?' · '+esc(a.details.name):'')+'</small></div></div>').join(''):'<div class="empty"><strong>No activity yet</strong><p>Changes in your vault will appear here.</p></div>'}
function checkDueReminders(){let now=Date.now(),due=reminders.filter(r=>!r.is_done&&!notifiedReminders.has(r.id)&&new Date(r.due_at).getTime()<=now);if(due.length){due.forEach(r=>notifiedReminders.add(r.id));toast(due.length+' reminder(s) are due.')}renderReminders()}
