$('list').addEventListener('click',async e=>{let nr=e.target.closest('[data-note-result]');if(nr){activeNote=nr.dataset.noteResult;switchPage('notes');renderNotesList();return}let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id;if(a==='folder-root'||a==='folder-up'){currentFolder=null;renderFiles();return}if(a==='open-folder'||a==='rename-folder'||a==='delete-folder')return folderAction(a,id);let f=files.find(x=>x.id===id);if(!f)return;try{if(a==='favorite'){let{error}=await db.from('jvault_files').update({is_favorite:!f.is_favorite}).eq('id',id);if(error)throw error;f.is_favorite=!f.is_favorite;await loadFiles()}if(a==='preview')await preview(f);if(a==='file-note')await editFileNote(f);if(a==='download'){let u=await signed(f,true);window.open(u,'_blank','noopener');await log('Downloaded file','file',id,{name:f.name})}if(a==='rename')await renameFile(f);if(a==='tags')await editTags(f);if(a==='category')await changeCategory(f);if(a==='move')await moveFile(f);if(a==='trash')await softDelete(f);if(a==='restore')await restoreFile(f);if(a==='purge')await purgeFile(f);if(a==='versions')await versions(f);if(a==='share')await shareFile(f)}catch(x){toast(x.message||'Action failed',true)}});
$('newNote').onclick=()=>createNote();$('notesList').onclick=async e=>{let b=e.target.closest('[data-note-id]');if(!b)return;clearTimeout(noteTimer);await saveNote();activeNote=b.dataset.noteId;renderNotesList()};['noteTitle','noteContent'].forEach(id=>$(id).addEventListener('input',()=>{ $('noteSaveStatus').textContent='Unsaved changes…';$('noteChars').textContent=$('noteContent').value.length.toLocaleString()+' characters';clearTimeout(noteTimer);noteTimer=setTimeout(saveNote,650)}));$('pinNote').onclick=()=>noteAction('pin');$('archiveNote').onclick=()=>noteAction('archive');$('deleteNote').onclick=()=>noteAction('delete');$('copyNote').onclick=async()=>{await navigator.clipboard.writeText($('noteContent').value);toast('Note copied')};document.querySelector('.format-tools').insertAdjacentHTML('beforeend','<button id="noteTags" class="text-btn">Tags</button><button id="linkNoteFile" class="text-btn">Link file</button><button id="exportNote" class="text-btn">Export</button>');$('noteTags').onclick=async()=>{let n=pages.find(x=>x.id===activeNote);if(!n)return;let value=prompt('Note tags, separated by commas',(n.tags||[]).join(', '));if(value===null)return;let tags=[...new Set(value.split(',').map(t=>t.trim().toLowerCase()).filter(Boolean))];let{error}=await db.from('jvault_pages').update({tags,updated_at:new Date().toISOString()}).eq('id',n.id);if(error)return toast(error.message,true);n.tags=tags;toast('Note tags saved')};$('linkNoteFile').onclick=()=>{let n=pages.find(x=>x.id===activeNote);if(!n)return;modal('Link note to a file','<select id="relatedFile"><option value="">No linked file</option>'+files.filter(f=>!f.deleted_at).map(f=>'<option value="'+f.id+'" '+(n.related_file_id===f.id?'selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select>','<button class="secondary-btn" data-modal-close>Cancel</button><button id="saveNoteLink" class="primary-btn">Save link</button>');$('saveNoteLink').onclick=async()=>{let{error}=await db.from('jvault_pages').update({related_file_id:$('relatedFile').value||null}).eq('id',n.id);if(error)return toast(error.message,true);n.related_file_id=$('relatedFile').value||null;$('modalRoot').innerHTML='';toast('File link saved')}};$('exportNote').onclick=()=>{let n=pages.find(x=>x.id===activeNote);if(!n)return;let blob=new Blob(['# '+n.title+'\\n\\n'+n.content],{type:'text/markdown'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(n.title||'note').replace(/[^a-z0-9-_ ]/gi,'')+'.md';a.click();URL.revokeObjectURL(url)};$('previewNote').onclick=()=>{$('notePreview').textContent=$('noteContent').value;$('notePreview').classList.toggle('hidden');$('noteContent').classList.toggle('hidden')};document.querySelectorAll('[data-wrap],[data-prefix]').forEach(b=>b.onclick=()=>{let t=$('noteContent'),start=t.selectionStart,end=t.selectionEnd,val=t.value;if(b.dataset.wrap){t.setRangeText(b.dataset.wrap+val.slice(start,end)+b.dataset.wrap,start,end,'select')}else{let line=val.slice(0,start).lastIndexOf('\\n')+1;t.setRangeText(b.dataset.prefix,line,line,'end')}t.dispatchEvent(new Event('input'))});
$('reminderForm').onsubmit=async e=>{e.preventDefault();let title=$('reminderTitle').value.trim(),due=new Date($('reminderDate').value);if(!title||isNaN(due)||due.getTime()<=Date.now())return toast('Choose a future date and time for this reminder.',true);let{error}=await db.from('jvault_reminders').insert({owner_id:user.id,title,due_at:due.toISOString()});if(error)return toast(error.message,true);$('reminderForm').reset();await loadReminders();await log('Created reminder','reminder',null,{title})};$('reminderList').addEventListener('change',async e=>{let id=e.target.dataset.reminderDone;if(!id)return;let{error}=await db.from('jvault_reminders').update({is_done:e.target.checked,updated_at:new Date().toISOString()}).eq('id',id);if(error)return toast(error.message,true);await loadReminders()});$('reminderList').addEventListener('click',async e=>{let id=e.target.dataset.reminderDelete;if(!id)return;if(!confirm('Delete this reminder?'))return;let{error}=await db.from('jvault_reminders').delete().eq('id',id);if(error)return toast(error.message,true);await loadReminders()});
